FEATURES={"FREE":{"PULSE","TIMER","BASIC_ANALYSIS","NEXT_LIMITED"},"PRO":{"PULSE","TIMER","FULL_ANALYSIS","NEXT_CANDLE","STRUCTURE","LIQUIDITY","RISK_PLAN","PERFORMANCE"},"ELITE":{"PULSE","TIMER","FULL_ANALYSIS","NEXT_CANDLE","STRUCTURE","LIQUIDITY","RISK_PLAN","PERFORMANCE","WATCH","AUTO_ALERT","ADVANCED_STATS","JOURNAL"},"SPECIAL":{"*"},"INTERNAL":{"*"}}
def allowed(plan,feature): return "*" in FEATURES.get(plan,set()) or feature in FEATURES.get(plan,set())
